'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var Float32Array = require( '@stdlib/array/float32' );
var Float64Array = require( '@stdlib/array/float64' );
var reinterpret64 = require( '@stdlib/strided/base/reinterpret-complex64' );
var reinterpret128 = require( '@stdlib/strided/base/reinterpret-complex128' );
var factory = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the prototype of the returned constructor is a `reverse` method (complex128)', function test( t ) {
	var Complex128Array = factory( 'complex128' );
	t.strictEqual( hasOwnProp( Complex128Array.prototype, 'reverse' ), true, 'has property' );
	t.strictEqual( isFunction( Complex128Array.prototype.reverse ), true, 'has method' );
	t.end();
});

tape( 'attached to the prototype of the returned constructor is a `reverse` method (complex64)', function test( t ) {
	var Complex64Array = factory( 'complex64' );
	t.strictEqual( hasOwnProp( Complex64Array.prototype, 'reverse' ), true, 'has property' );
	t.strictEqual( isFunction( Complex64Array.prototype.reverse ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a complex number array instance (complex128)', function test( t ) {
	var Complex128Array;
	var values;
	var arr;
	var i;

	Complex128Array = factory( 'complex128' );
	arr = new Complex128Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.reverse.call( value );
		};
	}
});

