tape( 'the method reverses elements of a complex number array in-place (complex128)', function test( t ) {
	var Complex128Array;
	var expected;
	var arr;
	var out;

	Complex128Array = factory( 'complex128' );
	arr = new Complex128Array( [ 1.0, -1.0, 2.0, -2.0, 3.0, -3.0 ] );
	expected = new Float64Array( [ 3.0, -3.0, 2.0, -2.0, 1.0, -1.0 ] );
	out = arr.reverse();

	t.strictEqual( instanceOf( arr, Complex128Array ), true, 'returns expected value' );
	t.strictEqual( out, arr, 'returns expected value' );
	t.strictEqual( arr.length, expected.length/2, 'returns expected value' );
	t.deepEqual( reinterpret128( arr, 0 ), expected, 'returns expected value' );
	t.end();
});

tape( 'the method reverses elements of a complex number array in-place (complex64)', function test( t ) {
	var Complex64Array;
	var expected;
	var arr;
	var out;

	Complex64Array = factory( 'complex64' );
	arr = new Complex64Array( [ 1.0, -1.0, 2.0, -2.0, 3.0, -3.0 ] );
	expected = new Float32Array( [ 3.0, -3.0, 2.0, -2.0, 1.0, -1.0 ] );
	out = arr.reverse();

	t.strictEqual( instanceOf( arr, Complex64Array ), true, 'returns expected value' );
	t.strictEqual( out, arr, 'returns expected value' );
	t.strictEqual( arr.length, expected.length/2, 'returns expected value' );
	t.deepEqual( reinterpret64( arr, 0 ), expected, 'returns expected value' );
	t.end();
});

